export const getVehicleImage = (id: string): string => {
  const realPhoto = VEHICLE_PHOTOS[id];
  if (realPhoto) return withCorsProxyOnWeb(realPhoto);
  const brand = VEHICLE_BRAND[id];
  if (brand && BRAND_LOGOS[brand]) return withCorsProxyOnWeb(BRAND_LOGOS[brand]);
  if (brand) return textBadgeFallback(brand); // gerçek logo bulunamayan marka (örn. Bentley, Skywell)
  return withCorsProxyOnWeb(ENGINE_BAY_IMAGE);
};

export const getBrandLogo = (brandName: string): string => {
  if (BRAND_LOGOS[brandName]) return withCorsProxyOnWeb(BRAND_LOGOS[brandName]);
  return textBadgeFallback(brandName);
};

// Bazı markaların (örn. Bentley Motors, Skywell) Wikimedia Commons'ta gerçek, doğrulanmış
// bir logo dosyası bulunmuyor — bu durumda uydurma bir link kullanmak yerine, marka adının
// baş harfleriyle temiz bir rozet oluşturuyoruz (ui-avatars.com, telif hakkı sorunu olmayan
// basit bir metin/baş harf görseli servisi). Bu, kullanıcıya "logo yok, marka adı burada"
// mesajını net şekilde verir; alakasız bir motor fotoğrafı göstermekten daha dürüst bir çözüm.
function textBadgeFallback(brandName: string): string {
  const initials = brandName
    .split(' ')
    .map((w) => w[0])
    .join('')
    .slice(0, 3)
    .toUpperCase();
  return `https://ui-avatars.com/api/?name=${encodeURIComponent(initials)}&background=11161C&color=FF8A3D&size=256&bold=true&format=png`;
}

// Web'de (react-native-web / tarayıcı) tarayıcının CORS kısıtlaması nedeniyle
// commons.wikimedia.org'dan doğrudan görsel çekilemiyor (bkz. konsol hatası:
// "blocked by CORS policy"). images.weserv.nl, herkese açık, ücretsiz bir görsel
// proxy'si; kaynak görseli indirip CORS başlığı ekleyerek yeniden sunuyor.
// Native (Android/iOS) tarafında bu kısıtlama yok, o yüzden sadece web'de devrede.
function withCorsProxyOnWeb(url: string): string {
  if (Platform.OS !== 'web') return url;
  if (url.startsWith('data:')) return url; // base64 gömülü görseller zaten CORS sorunu yaşamaz, proxy'ye gerek yok
  const withoutProtocol = url.replace(/^https?:\/\//, '');
  return `https://images.weserv.nl/?url=${encodeURIComponent(withoutProtocol)}`;
}
